const VINA_THEME_KEY='vina-appearance';
function applyVinaTheme(theme){const selected=theme==='dark'?'dark':'light';document.documentElement.dataset.theme=selected;document.documentElement.style.colorScheme=selected;const themeMeta=document.querySelector('meta[name="theme-color"]');if(themeMeta)themeMeta.setAttribute('content',selected==='dark'?'#1c1917':'#f7f5f0');const toggle=document.querySelector('#vina-theme-toggle');if(toggle){toggle.textContent=selected==='dark'?'☀ Світла':'☾ Темна';toggle.setAttribute('aria-label',selected==='dark'?'Увімкнути світлу тему':'Увімкнути темну тему');toggle.setAttribute('aria-pressed',String(selected==='dark'))}}
function initVinaTheme(){let saved;try{saved=localStorage.getItem(VINA_THEME_KEY)}catch{}applyVinaTheme(saved==='dark'||saved==='light'?saved:(window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));let toggle=document.querySelector('#vina-theme-toggle');if(!toggle){toggle=document.createElement('button');toggle.id='vina-theme-toggle';toggle.type='button';toggle.className='vina-theme-toggle';const headerActions=document.querySelector('main>header .header-right');(headerActions||document.body).prepend(toggle)}applyVinaTheme(document.documentElement.dataset.theme);toggle.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem(VINA_THEME_KEY,next)}catch{}applyVinaTheme(next)})}
initVinaTheme();

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
async function api(path,options={}){const r=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{...(options.body?{'content-type':'application/json'}:{}),...options.headers}});let data;try{data=await r.json()}catch{throw Error('Сервер не відповів коректно')}if(!r.ok)throw Error(data.error||'Помилка сервера');return data}
const post=(path,data)=>api(path,{method:'POST',body:JSON.stringify(data)});
function msg(text){notice.hidden=!text;notice.textContent=text}
let toastTimer;function toast(text){let el=$('#vina-toast');if(!el){el=document.createElement('div');el.id='vina-toast';el.className='vina-toast';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.append(el)}clearTimeout(toastTimer);el.textContent=text;el.classList.add('is-visible');toastTimer=setTimeout(()=>el.classList.remove('is-visible'),3600)}
const loadingRows=(count=3)=>'<div class="vina-skeleton-list" role="status" aria-label="Завантаження даних">'+Array.from({length:count},(_,i)=>'<div class="vina-skeleton-row"><span class="vina-skeleton-avatar"></span><span class="vina-skeleton-copy"><span class="vina-skeleton-line"></span><span class="vina-skeleton-line short"></span></span></div>').join('')+'</div>';
const loadingMetric='<span class="vina-skeleton-metric" role="status" aria-label="Завантаження показника"></span>';
function revealMetrics(root=document){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||document.hidden)return;root.querySelectorAll('.metric').forEach(el=>{const value=Number(el.textContent.trim());if(!Number.isInteger(value)||value<0||value>9999||el.dataset.animatedValue===String(value))return;el.dataset.animatedValue=String(value);const duration=360,start=performance.now();function tick(now){if(!el.isConnected||document.hidden)return;const progress=Math.min((now-start)/duration,1);el.textContent=String(Math.round(value*(1-Math.pow(1-progress,3))));if(progress<1)requestAnimationFrame(tick);else el.textContent=String(value)}requestAnimationFrame(tick)})}
function pending(button,active,label='Зачекайте…'){if(!button)return;if(active){if(button.disabled)return;button.dataset.originalLabel=button.textContent;button.disabled=true;button.classList.add('vina-pending');button.textContent=label;button.setAttribute('aria-busy','true')}else{button.disabled=false;button.classList.remove('vina-pending');button.textContent=button.dataset.originalLabel||button.textContent;button.removeAttribute('aria-busy')}}

function confirmAction(message,{title='Підтвердження дії',confirmLabel='Підтвердити',danger=false}={}){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='vina-confirm';d.innerHTML='<div class="vina-confirm-icon" aria-hidden="true">✓</div><h2>'+esc(title)+'</h2><p>'+esc(message)+'</p><div class="actions"><button type="button" class="ghost" data-cancel>Скасувати</button><button type="button" class="button'+(danger?' vina-danger':'')+'" data-confirm>'+esc(confirmLabel)+'</button></div>';document.body.append(d);let settled=false;function finish(value){if(settled)return;settled=true;resolve(value);d.close()}d.querySelector('[data-cancel]').onclick=()=>finish(false);d.querySelector('[data-confirm]').onclick=()=>finish(true);d.addEventListener('cancel',e=>{e.preventDefault();finish(false)});d.addEventListener('close',()=>{if(!settled){settled=true;resolve(false)}d.remove()});d.showModal();d.querySelector('[data-confirm]').focus()})}
