function form(title,fields,button){content.innerHTML='<div class="vina-auth-layout"><section class="vina-auth-story"><div class="vina-auth-story-head"><span>VINA</span><span>COFFEE · WORKSPACE</span></div><div class="vina-auth-story-body"><span class="vina-auth-kicker">ПРОСТІР VINA</span><h2>Турбота<br>у кожній <em>деталі.</em></h2><p>Створено для людей, які щодня створюють атмосферу VINA.</p></div><div class="vina-auth-story-foot"><span>ПРОДУМАНО ДЛЯ ЩОДЕННОЇ РОБОТИ</span><span>✳</span></div></section><section class="vina-auth-panel"><div class="vina-auth-panel-top"><span>ЗАХИЩЕНИЙ ДОСТУП</span><span>01 / VINA</span></div><div class="vina-auth-form-wrap"><span class="vina-auth-welcome">РАДІ ВАС БАЧИТИ</span><h2 class="vina-auth-title">'+title+'</h2><p class="vina-auth-description">Увійдіть до свого робочого простору.</p><form id="auth-form">'+fields+'<button class="button" type="submit">'+button+' <span aria-hidden="true">↗</span></button></form><p class="vina-auth-footnote">Ваш обліковий запис захищений серверною авторизацією.</p></div><div class="vina-auth-panel-foot">VINA COFFEE <span>РОБОЧИЙ ПРОСТІР</span></div></section></div>';return $('#auth-form')}
function input(label,name,type='text',autocomplete='off'){return '<label>'+label+'<input name="'+name+'" type="'+type+'" autocomplete="'+autocomplete+'" required></label>'}
function viewMode(mode){document.body.dataset.view=mode;if(mode!=='admin'){document.querySelector('#vina-mobile-nav')?.remove();document.querySelector('#vina-mobile-menu')?.remove();document.body.classList.remove('vina-menu-open')};$('.subtitle').textContent=mode==='staff'?'STAFF':mode==='auth'?'COFFEE':'DATA CENTRE';document.title=mode==='staff'?'VINA Staff':mode==='auth'?'Вхід · VINA Coffee':'VINA Data Centre';$('.eyebrow').textContent=mode==='auth'?'VINA COFFEE':mode==='staff'?'VINA / STAFF':'VINA / УПРАВЛІННЯ'}
async function start(){viewMode('auth');currentUser=null;msg('');$('#logout').hidden=true;$('#change-password').hidden=true;document.querySelector('nav').innerHTML='';try{const me=await api('auth/me');return dashboard(me.user)}catch{}try{const status=await api('auth/setup-status');if(status.setupRequired&&status.setupEnabled)return setup();if(status.setupRequired){heading('Початкове налаштування','Для створення власника необхідний одноразовий секрет Cloudflare.');msg('У Cloudflare Worker додайте секрет OWNER_SETUP_TOKEN. Не передавайте його в чат і не зберігайте в GitHub.');return}return login()}catch(e){heading('Не вдалося підключитися','Перевірте Cloudflare D1 та розгортання Worker.');msg(e.message)}}
function setup(){viewMode('auth');$('#logout').hidden=true;$('#change-password').hidden=true;document.querySelector('nav').innerHTML='';heading('Створення власника','Початкове налаштування виконується лише один раз.');const f=form('Обліковий запис власника',input('Ім’я для входу','name')+input('Пароль (мінімум 8 символів)','password','password','new-password')+input('Секрет OWNER_SETUP_TOKEN','token','password'),'Створити власника');f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if(d.password.length<8){msg('Пароль має містити щонайменше 8 символів');return}const button=f.querySelector('[type=submit]');if(button.disabled)return;pending(button,true,'Створюємо…');try{await post('auth/setup',d);login();toast('Власника створено. Видаліть OWNER_SETUP_TOKEN у Cloudflare.')}catch(err){msg(err.message)}finally{if(button.isConnected)pending(button,false)}}}
function login(){viewMode('auth');$('#logout').hidden=true;$('#change-password').hidden=true;document.querySelector('nav').innerHTML='';heading('З поверненням!','Увійдіть, щоб розпочати робочий день.');const f=form('Вхід до VINA',input('Ім’я','name','text','username')+input('Пароль','password','password','current-password'),'Увійти');f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');if(button.disabled)return;pending(button,true,'Входимо…');try{const d=Object.fromEntries(new FormData(f));const r=await post('auth/login',d);msg('');await dashboard(r.user)}catch(err){msg(err.message)}finally{if(button.isConnected)pending(button,false)}}}
