document.addEventListener('click',e=>{if(e.target.closest('#vina-mobile-more')){const menu=$('#vina-mobile-menu');if(!menu)return;const next=menu.hidden;menu.hidden=!next;document.body.classList.toggle('vina-menu-open',next);$('#vina-mobile-more').setAttribute('aria-expanded',String(next));return}if(e.target.closest('#vina-mobile-close')||e.target.closest('#vina-mobile-menu [data-page]'))closeMobileMenu()});
