async function adminTasks(){
const requestId=pageRequestId;
content.innerHTML='<div class="vina-tasks-admin"><div class="toolbar"><div><h2 class="section-title">Щоденні завдання</h2><p class="muted">Список для персоналу. Відключені завдання приховані від бариста.</p></div><form id="vina-new-task" class="vina-new-task"><label class="sr-only" for="vina-task-title">Назва завдання</label><input id="vina-task-title" name="title" required minlength="3" maxlength="120" placeholder="Нове завдання" autocomplete="off"><button type="submit" class="button">+ Додати</button></form></div><div id="vina-admin-task-list" class="card">'+loadingRows(3)+'</div><section class="vina-task-report"><div class="row"><div><h2 class="section-title">Виконання сьогодні</h2><p class="muted" id="vina-task-report-date">Завантажуємо записи…</p></div><button type="button" class="ghost" id="vina-task-report-refresh">Оновити ↻</button></div><div id="vina-task-completions" class="card">'+loadingRows(2)+'</div></section></div>';
const operationsSection=document.createElement('section');operationsSection.className='card vina-operations-section';operationsSection.innerHTML='<h2>📣 Заходи та оголошення</h2><p class="muted">Заплануйте публікацію, прибирання, переоблік або інформацію про святкову оплату.</p><div id="vina-operations"></div>';content.querySelector('.vina-tasks-admin').append(operationsSection);renderOperations(true);
const refreshReport=async()=>{const host=$('#vina-task-completions');if(!host)return;try{const report=await api('tasks/completions');if(requestId!==pageRequestId||currentPage!=='tasks'||!$('#vina-task-completions'))return;const rows=report.completions||[];$('#vina-task-report-date').textContent='Сьогодні · '+report.date+' · '+rows.length+' виконань';host.innerHTML=rows.length?'<div class="vina-task-list">'+rows.map(c=>'<div class="vina-task-row"><div><strong>'+esc(c.title)+'</strong><small>'+esc(c.display_name)+' · '+esc(dateTime(c.completed_at))+'</small></div><span class="vina-task-done">✓ Виконано</span></div>').join('')+'</div>':'<div class="overview-empty">Сьогодні виконаних завдань поки немає.</div>'}catch(err){if(requestId===pageRequestId&&$('#vina-task-completions'))$('#vina-task-completions').textContent='Не вдалося завантажити виконання: '+err.message}};
$('#vina-task-report-refresh').onclick=async e=>{const b=e.currentTarget;pending(b,true,'Оновлюємо…');try{await refreshReport()}finally{if(b.isConnected)pending(b,false)}};
refreshReport();
const form=$('#vina-new-task');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');pending(b,true,'Додаємо…');try{await post('tasks',{title:form.elements.title.value});toast('Завдання додано');await adminTasks()}catch(err){msg(err.message);pending(b,false)}};
try{const data=await api('tasks');if(requestId!==pageRequestId||currentPage!=='tasks')return;const host=$('#vina-admin-task-list');host.innerHTML=data.tasks.length?'<div class="vina-task-list">'+data.tasks.map(t=>'<div class="vina-task-row"><div><strong>'+esc(t.title)+'</strong><small>'+(t.active?'Активне':'Вимкнене')+'</small></div><div class="vina-task-admin-actions"><button type="button" class="ghost" data-task-edit="'+esc(t.id)+'">Редагувати</button><button type="button" class="ghost" data-task-status="'+esc(t.id)+'" data-next="'+(!t.active)+'">'+(t.active?'Вимкнути':'Увімкнути')+'</button></div></div>').join('')+'</div>':'<div class="overview-empty">Завдань ще немає. Створіть перше завдання для команди.</div>';host.querySelectorAll('[data-task-edit]').forEach(button=>button.onclick=()=>{
 const task=data.tasks.find(t=>t.id===button.dataset.taskEdit);if(!task)return;
 const row=button.closest('.vina-task-row');if(!row)return;
 const original=row.innerHTML;
 row.innerHTML='<form class="vina-task-edit-form"><label>Назва завдання<input name="title" minlength="3" maxlength="120" required></label><div class="vina-task-admin-actions"><button type="submit" class="button">Зберегти</button><button type="button" class="ghost" data-cancel>Скасувати</button></div></form>';
 const form=row.querySelector('form');form.elements.title.value=task.title;form.elements.title.focus();
 row.querySelector('[data-cancel]').onclick=()=>{row.innerHTML=original;adminTasks()};
 form.onsubmit=async event=>{event.preventDefault();const save=form.querySelector('[type=submit]');pending(save,true,'Зберігаємо…');try{await api('tasks/'+task.id,{method:'PATCH',body:JSON.stringify({title:form.elements.title.value})});toast('Завдання оновлено');await adminTasks()}catch(error){msg(error.message);pending(save,false)}};
});
host.querySelectorAll('[data-task-status]').forEach(b=>b.onclick=async()=>{pending(b,true,'Зберігаємо…');try{await post('tasks/'+b.dataset.taskStatus+'/status',{active:b.dataset.next==='true'});toast('Статус завдання оновлено');await adminTasks()}catch(err){msg(err.message);pending(b,false)}})}catch(err){msg('Не вдалося завантажити завдання: '+err.message)}
}
async function team(){content.innerHTML='<div class="toolbar"><span class="muted">Працівники з Cloudflare D1 · ролі та доступ</span>'+(currentUser.role==='owner'?'<button class="button" id="new-staff">+ Додати працівника</button>':'')+'</div><div id="staff-list" class="card">'+loadingRows(4)+'</div>';try{const r=await api('staff');$('#staff-list').innerHTML=r.staff.length?'<div class="vina-team-list">'+r.staff.map(s=>'<article class="vina-team-person"><div class="vina-team-avatar" aria-hidden="true">'+esc((s.display_name||'?').slice(0,1).toUpperCase())+'</div><div class="vina-team-info"><strong>'+esc(s.display_name)+'</strong><span>'+esc(({owner:'Власник',manager:'Менеджер',barista:'Бариста'})[s.role]||s.role)+' · '+esc(s.rank)+'</span></div><div class="vina-team-controls"><span class="vina-team-state '+(s.active?'is-active':'is-inactive')+'"><i aria-hidden="true"></i>'+(s.active?'Активний':'Вимкнений')+'</span>'+(currentUser.role==='owner'&&s.role!=='owner'?'<button class="vina-team-access" data-toggle="'+esc(s.id)+'" data-active="'+(s.active?'0':'1')+'">'+(s.active?'Вимкнути доступ':'Увімкнути доступ')+'</button>':'')+'</div></article>').join('')+'</div>':'<div class="empty">Працівників поки немає</div>';}catch(e){msg(e.message)}
const add=$('#new-staff');if(add)add.onclick=()=>{const d=document.createElement('dialog');d.innerHTML='<form id="staff-form"><h2>Новий працівник</h2>'+input('Ім’я для входу','name')+'<label>Роль<select name="role"><option value="barista">Бариста</option><option value="manager">Менеджер</option></select></label>'+input('Пароль (бариста від 4, менеджер від 8 символів)','password','password','new-password')+'<div class="actions"><button class="ghost" type="button" id="cancel-staff">Скасувати</button><button class="button">Створити</button></div></form>';document.body.append(d);d.querySelector('#cancel-staff').onclick=()=>d.close();d.onclose=()=>d.remove();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await post('staff',data);d.close();await team();toast('Працівника створено. Передайте дані для входу безпечним способом.')}catch(err){msg(err.message)}};d.showModal()}}
document.addEventListener('click',async e=>{const page=e.target.closest('[data-page]');if(page){if(page.dataset.page===currentPage)return;const destination=page.dataset.page;content.classList.remove('vina-content-entering','vina-content-leaving');showPage(destination);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){content.classList.add('vina-content-entering');setTimeout(()=>content.classList.remove('vina-content-entering'),380)}return}const toggle=e.target.closest('[data-toggle]');if(toggle){const active=toggle.dataset.active==='1';if(!(await confirmAction(active?'Відновити доступ цього працівника?':'Доступ буде вимкнено, а активні сесії працівника завершено.',{title:active?'Увімкнути доступ?':'Вимкнути доступ?',confirmLabel:active?'Увімкнути':'Вимкнути',danger:!active})))return;pending(toggle,true);try{await post('staff/'+toggle.dataset.toggle+'/status',{active});await team();toast(active?'Доступ увімкнено':'Доступ вимкнено')}catch(err){msg(err.message)}finally{if(toggle.isConnected)pending(toggle,false)}}});
function passwordDialog(){const d=document.createElement('dialog');d.innerHTML='<form id="password-form"><h2>Змінити пароль</h2>'+input('Поточний пароль','currentPassword','password','current-password')+input('Новий пароль (бариста від 4, інші від 8 символів)','newPassword','password','new-password')+input('Повторіть новий пароль','confirmPassword','password','new-password')+'<div class="actions"><button type="button" class="ghost" id="cancel-password">Скасувати</button><button class="button">Зберегти пароль</button></div><p id="password-error" role="alert"></p></form>';document.body.append(d);d.querySelector('#cancel-password').onclick=()=>d.close();d.onclose=()=>d.remove();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));const error=d.querySelector('#password-error');if(values.newPassword.length<(currentUser?.role==='barista'?4:8)){error.textContent='Пароль занадто короткий для вашої ролі';return}if(values.newPassword!==values.confirmPassword){error.textContent='Нові паролі не збігаються';return}try{await post('auth/change-password',{currentPassword:values.currentPassword,newPassword:values.newPassword});d.close();await start();toast('Пароль змінено. Увійдіть із новим паролем.')}catch(err){error.textContent=err.message}};d.showModal()}
const changeButton=document.createElement('button');changeButton.className='ghost';changeButton.textContent='Змінити пароль';changeButton.id='change-password';changeButton.hidden=true;$('#logout').before(changeButton);changeButton.onclick=passwordDialog;
$('#logout').onclick=async()=>{try{await post('auth/logout',{})}catch{}currentUser=null;$('#logout').hidden=true;$('#change-password').hidden=true;await start()};Promise.resolve(start()).catch(e=>{console.error('VINA startup error',e);msg('Не вдалося завантажити систему. Оновіть сторінку.')}).finally(()=>setTimeout(hideSplash,180));
